function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function selectedYears(){const n=Number($('#historyWindow')?.value||5);return YEARS.slice(0,n)}
function windowLabel(){const n=Number($('#historyWindow')?.value||5);return n===1?'2026–27 only':n===5?'all 5 years':`last ${n} years`}
function places(u,y){const h=u.history[y],v=h?.places;return v==null?(h?.noPlaces?'—':h?.noData?'—':'?'):v}
function tempText(v){return Number.isFinite(v)?`${v.toFixed(1)}°C`:'…'}
function climateValue(c,key){if(!c)return null;if(key==='AVG'){const vals=['SEP','OCT','NOV','DEC'].map(k=>c[k]).filter(Number.isFinite);return vals.length===4?vals.reduce((a,b)=>a+b,0)/4:null}return Number.isFinite(c[key])?c[key]:null}
function formatRank(rank){const s=String(rank||'');return /^\d+$/.test(s)?`#${s}`:s.replace('-', '–')}
function rankText(u){if(!state.arwuReady)return '…';if(u.arwuRank)return formatRank(u.arwuRank);return 'No ARWU match'}
function continent(u){return CONTINENT_BY_COUNTRY[u.country]||'Other'}
function costIndex(u){const v=COST_RENT_2026[u.country];return Number.isFinite(v)?v:null}
function profile(u){return state.profiles.get(u.id)||null}
function foundedYear(u){const y=profile(u)?.foundedYear;return Number.isFinite(y)?y:null}
function ageText(year){if(!Number.isFinite(year))return 'Unknown';const age=Math.max(0,new Date().getFullYear()-year);return `${year} · about ${age} years old`}
function heritageLabel(year){if(!Number.isFinite(year))return null;if(year<1800)return 'Very old institution';if(year<1900)return 'Historic institution';if(year<1950)return 'Long-established institution';return 'Modern institution'}
function yearsOld(year){return Number.isFinite(year)?Math.max(0,new Date().getFullYear()-year):null}
function selectedText(id){const el=$('#'+id);return el?.selectedOptions?.[0]?.textContent?.trim()||''}
function activeFilterDescriptors(){
  const out=[];
  const q=$('#search')?.value.trim();
  if(q)out.push({key:'search',label:`Search: “${q}”`});
  if($('#country')?.value)out.push({key:'country',label:`Country: ${selectedText('country')}`});
  if($('#continent')?.value)out.push({key:'continent',label:`Continent: ${selectedText('continent')}`});
  if($('#minPlaces')?.value&&$('#minPlaces').value!=='0')out.push({key:'minPlaces',label:`Places: ${selectedText('minPlaces')}`});
  if($('#historyWindow')?.value&&$('#historyWindow').value!=='5')out.push({key:'historyWindow',label:`History: ${selectedText('historyWindow')}`});
  if($('#demandLevel')?.value)out.push({key:'demandLevel',label:`CBS demand: ${selectedText('demandLevel')}`});
  if($('#arwuMax')?.value&&$('#arwuMax').value!=='0')out.push({key:'arwuMax',label:`ARWU: ${selectedText('arwuMax')}`});
  if($('#minTemp')?.value!=='')out.push({key:'temperature',label:`Temperature · ${selectedText('tempMetric')}: ${selectedText('minTemp')}`});
  if($('#maxCost')?.value!=='')out.push({key:'maxCost',label:`Cost + rent: ${selectedText('maxCost')}`});
  if($('#foundedBefore')?.value!=='')out.push({key:'foundedBefore',label:`University age: ${selectedText('foundedBefore')}`});
  if($('#last2')?.checked)out.push({key:'last2',label:'Places available in both latest years'});
  return out;
}
function resetFilter(key){
  if(key==='search')$('#search').value='';
  else if(key==='country')$('#country').value='';
  else if(key==='continent')$('#continent').value='';
  else if(key==='minPlaces')$('#minPlaces').value='0';
  else if(key==='historyWindow')$('#historyWindow').value='5';
  else if(key==='demandLevel')$('#demandLevel').value='';
  else if(key==='arwuMax')$('#arwuMax').value='0';
  else if(key==='temperature'){ $('#minTemp').value=''; $('#tempMetric').value='AVG'; }
  else if(key==='maxCost')$('#maxCost').value='';
  else if(key==='foundedBefore')$('#foundedBefore').value='';
  else if(key==='last2')$('#last2').checked=false;
  applyFilters();
}
function resetAllFilters(){
  $('#search').value='';$('#country').value='';$('#continent').value='';$('#minPlaces').value='0';$('#historyWindow').value='5';$('#demandLevel').value='';$('#arwuMax').value='0';$('#tempMetric').value='AVG';$('#minTemp').value='';$('#maxCost').value='';$('#foundedBefore').value='';$('#last2').checked=false;applyFilters();
}
function renderActiveFilters(){
  const box=$('#activeFilters'),items=activeFilterDescriptors(),count=$('#filterCount');
  if(count){count.textContent=items.length;count.setAttribute('aria-label',`${items.length} active filter${items.length===1?'':'s'}`);count.classList.toggle('has-filters',items.length>0)}
  if(!box)return;
  if(!items.length){box.hidden=true;box.innerHTML='';return}
  box.hidden=false;
  box.innerHTML=`<span class="active-filter-label">Active filters</span>${items.map(x=>`<button type="button" class="filter-chip" data-clear-filter="${esc(x.key)}"><span>${esc(x.label)}</span><b aria-hidden="true">×</b><span class="sr-only">Remove ${esc(x.label)}</span></button>`).join('')}<button type="button" class="clear-filter-chips" data-clear-all>Clear all</button>`;
  box.querySelectorAll('[data-clear-filter]').forEach(b=>b.addEventListener('click',()=>resetFilter(b.dataset.clearFilter)));
  box.querySelector('[data-clear-all]')?.addEventListener('click',resetAllFilters);
}

function competitionSummary(u){
  const years=selectedYears();
  const allObs=years.map(year=>({year,status:u.history[year]?.status||'unknown'}));
  const obs=allObs.filter(x=>Number.isFinite(STATUS_META[x.status]?.order));
  if(!obs.length)return{status:'unknown',order:null,observed:0,selected:years.length,excluded:years.length,override:null,base:'unknown'};
  const counts={};for(const x of obs)counts[x.status]=(counts[x.status]||0)+1;
  const maxCount=Math.max(...Object.values(counts));
  const candidates=new Set(Object.keys(counts).filter(k=>counts[k]===maxCount));
  const base=obs.find(x=>candidates.has(x.status)).status;
  let status=base,override=null;const baseOrder=STATUS_META[base].order;
  if(obs.length>=2&&obs[0].status===obs[1].status){const recentOrder=STATUS_META[obs[0].status].order;if(Math.abs(recentOrder-baseOrder)>=2){status=obs[0].status;override='two_recent'}}
  if(!override&&obs.length>=1){const recentOrder=STATUS_META[obs[0].status].order;if(Math.abs(recentOrder-baseOrder)>=3){status=obs[0].status;override='latest_extreme'}}
  return{status,order:STATUS_META[status].order,observed:obs.length,selected:years.length,excluded:years.length-obs.length,override,base,counts};
}
function availabilityInWindow(u){return selectedYears().filter(y=>u.history[y]?.status==='available').length}
function demandChip(status,label=null){const meta=STATUS_META[status]||STATUS_META.unknown;return `<span class="status-chip status-${esc(status)}">${esc(label||meta.short)}</span>`}
function summaryExplanation(s){
  if(s.status==='unknown')return 'No comparable CBS demand observation in the selected period.';
  let text='Most frequent comparable category in the selected period; ties favor the most recent year.';
  if(s.override==='two_recent')text='Recent shift applied: the two most recent comparable years agree and differ strongly from the older majority.';
  if(s.override==='latest_extreme')text='Recent shift applied: the latest comparable year is an extreme reversal from the older majority.';
  if(s.excluded)text+=` ${s.excluded} selected year${s.excluded===1?' was':'s were'} excluded because CBS recorded “No places” or “No data”.`;
  return text;
}
function markerIcon(u){const s=competitionSummary(u),m=STATUS_META[s.status]||STATUS_META.unknown;return L.divIcon({className:'',html:`<div class="uni-marker" style="background:${m.bg};border-color:${m.border}"></div>`,iconSize:[17,17],iconAnchor:[8,8]})}
function popupHtml(u){
  const c=state.climate.get(u.id),s=competitionSummary(u),avg=climateValue(c,'AVG'),fy=foundedYear(u),ci=costIndex(u);
  return `<div class="popup-name">${esc(u.name)}</div><div class="popup-meta">${esc(u.country)} · ${esc(continent(u))} · ${esc(windowLabel())}</div><div class="popup-facts"><div class="popup-demand">${demandChip(s.status)}</div><span>ARWU: <strong>${esc(rankText(u))}</strong></span>${Number.isFinite(avg)?`<span>Sep–Dec average: <strong>${tempText(avg)}</strong></span>`:''}${Number.isFinite(ci)?`<span>Cost+rent index: <strong>${ci.toFixed(1)}</strong></span>`:''}${Number.isFinite(fy)?`<span>Founded: <strong>${fy}</strong></span>`:''}</div><button class="popup-btn" data-detail="${u.id}">View details</button>`
}

function sortValue(u,key){
  if(key==='demandScore'){const s=competitionSummary(u);return s.order==null?99:s.order}
  if(key==='availabilityWindow')return availabilityInWindow(u);
  if(key==='costIndex')return costIndex(u);
  if(key==='foundedYear')return foundedYear(u);
  if(key.startsWith('temp')){const metric=key.slice(4);return climateValue(state.climate.get(u.id),metric)}
  return u[key];
}
function cmp(a,b,key,dir){let av=sortValue(a,key),bv=sortValue(b,key);const aNull=av==null||Number.isNaN(av),bNull=bv==null||Number.isNaN(bv);if(aNull&&bNull)return 0;if(aNull)return 1;if(bNull)return -1;if(typeof av==='string'||typeof bv==='string')return String(av).localeCompare(String(bv))*dir;return (av-bv)*dir}
function renderTable(){
  const body=$('#tableBody');if(!body)return;const rows=[...state.filtered].sort((a,b)=>cmp(a,b,state.sortKey,state.sortDir));
  body.innerHTML=rows.map(u=>{const c=state.climate.get(u.id),s=competitionSummary(u),fy=foundedYear(u),age=yearsOld(fy),ci=costIndex(u);return `<tr><td><button class="uni-link" data-detail="${u.id}">${esc(u.name)}</button><br><span class="muted">${esc(u.school||'Regular')}</span></td><td>${esc(u.country)}</td><td>${demandChip(s.status)}</td><td class="rank-cell ${u.arwuRank?'ranked':''}">${esc(rankText(u))}</td><td>${tempText(climateValue(c,'AVG'))}</td><td>${Number.isFinite(ci)?ci.toFixed(1):'—'}</td><td class="age-cell">${Number.isFinite(age)?`<strong>~${age} years</strong><span>Founded ${fy}</span>`:(profile(u)?'<span class="muted">Unknown</span>':'<span class="muted">Loading…</span>')}</td><td>${u.latestPlaces??'—'}</td><td>${availabilityInWindow(u)}/${selectedYears().length}</td><td><span class="badge ${u.availableLast2?'yes':'no'}">${u.availableLast2?'Yes':'No'}</span></td></tr>`}).join('');
  body.querySelectorAll('[data-detail]').forEach(b=>b.addEventListener('click',()=>openDetail(Number(b.dataset.detail))));
}
function renderMarkers(){
  layer.clearLayers();state.markers.clear();for(const u of state.filtered){const c=state.coords.get(u.id);if(!c)continue;const m=L.marker([c.lat,c.lon],{icon:markerIcon(u)}).bindPopup(popupHtml(u));m.on('popupopen',e=>{const btn=e.popup.getElement()?.querySelector('[data-detail]');if(btn)btn.onclick=()=>openDetail(Number(btn.dataset.detail))});m.addTo(layer);state.markers.set(u.id,m)}
}
function updateLegend(){const el=$('#legendWindow');if(el)el.textContent=`Map colors · ${windowLabel()}`}
function applyFilters(){
  const q=$('#search').value.trim().toLowerCase(),country=$('#country').value,cont=$('#continent').value,minP=Number($('#minPlaces').value||0),demand=$('#demandLevel').value,last2=$('#last2').checked;
  const arwuMax=Number($('#arwuMax').value||0),tempMetric=$('#tempMetric').value,minTemp=$('#minTemp').value===''?null:Number($('#minTemp').value),maxCost=$('#maxCost').value===''?null:Number($('#maxCost').value),foundedBefore=$('#foundedBefore').value===''?null:Number($('#foundedBefore').value);
  state.filtered=state.all.filter(u=>{const c=state.climate.get(u.id),s=competitionSummary(u),tv=climateValue(c,tempMetric),ci=costIndex(u),fy=foundedYear(u);return (!q||`${u.name} ${u.school} ${u.country}`.toLowerCase().includes(q))&&(!country||u.country===country)&&(!cont||continent(u)===cont)&&(u.latestPlaces??0)>=minP&&(!demand||s.status===demand)&&(!last2||u.availableLast2)&&(!arwuMax||(u.arwuSort&&u.arwuSort<=arwuMax))&&(minTemp==null||(Number.isFinite(tv)&&tv>=minTemp))&&(maxCost==null||(Number.isFinite(ci)&&ci<=maxCost))&&(foundedBefore==null||(Number.isFinite(fy)&&fy<foundedBefore))});
  $('#visibleCount').textContent=state.filtered.length;updateLegend();renderActiveFilters();renderMarkers();renderTable();
}

function climateDetails(c){if(!c)return `<p class="muted climate-wait">Climate is loading for this location…</p>`;const avg=climateValue(c,'AVG');return `<div class="climate-summary"><strong>${tempText(avg)}</strong><span>Sep–Dec average</span></div><details class="month-breakdown"><summary>Monthly breakdown</summary><div class="climate-grid">${[['SEP','Sep'],['OCT','Oct'],['NOV','Nov'],['DEC','Dec']].map(([k,l])=>`<div class="climate-card"><span>${l}</span><strong>${tempText(c[k])}</strong></div>`).join('')}</div></details>`}
function costDetails(u){const ci=costIndex(u);if(!Number.isFinite(ci))return `<strong>Not in the 2026 country index</strong><span class="muted">Numbeo has price pages for some smaller territories, but no comparable country index value is shown here.</span>`;return `<strong>${ci.toFixed(1)}</strong><span class="muted">2026 Mid-Year country Cost of Living + Rent Index. Lower is cheaper.</span>`}
function historyProfileHtml(u){const p=profile(u),fy=foundedYear(u);if(!p)return `<div class="history-profile loading-profile"><strong>Loading university history…</strong><span class="muted">Founded year and a short background note are being looked up from Wikidata/Wikipedia.</span></div>`;const badge=heritageLabel(fy);const source=p.wikiUrl?`<a href="${esc(p.wikiUrl)}" target="_blank" rel="noopener">Wikipedia</a>`:'Wikipedia';const wd=p.qid?` · <a href="https://www.wikidata.org/wiki/${esc(p.qid)}" target="_blank" rel="noopener">Wikidata</a>`:'';return `<div class="history-profile"><div class="history-profile-head"><div><span class="mini-label">Founded / institution age</span><strong>${esc(ageText(fy))}</strong>${badge?`<span class="heritage-badge">${esc(badge)}</span>`:''}</div></div><p>${p.extract?esc(p.extract):'No short English-language history summary was found automatically.'}</p><small>Sources: ${source}${wd}. Institution age does not guarantee that the exchange campus itself has old buildings.</small></div>`}
function openDetail(id){
  const u=state.all.find(x=>x.id===id);if(!u)return;state.currentDetailId=id;const c=state.climate.get(u.id),s=competitionSummary(u),windowSet=new Set(selectedYears());
  const rankMeta=state.arwuReady?(u.arwuRank?`<strong>${esc(formatRank(u.arwuRank))}</strong>${u.arwuMatchedInstitution&&u.arwuMatchedInstitution!==u.name?`<span class="muted">ARWU institution: ${esc(u.arwuMatchedInstitution)}</span>`:''}`:`<strong>No confident ARWU match</strong><span class="muted">This avoids guessing when the CBS partner name cannot be matched confidently to the published ARWU list.</span>`):'<strong>Rank data loading…</strong>';
  const shift=s.override?'<span class="recent-shift">Recent shift</span>':'';
  $('#detailContent').innerHTML=`<h2 class="detail-title">${esc(u.name)}</h2><p class="detail-sub">${esc(u.school||u.country)}${u.school?` · ${esc(u.country)}`:''} · ${esc(continent(u))}</p>
    <div class="detail-metrics">
      <div class="metric-card"><span>CBS demand · ${esc(windowLabel())}</span><div class="demand-summary">${demandChip(s.status)}${shift}</div><small>${s.observed}/${s.selected} selected years comparable</small></div>
      <div class="metric-card"><span>ARWU 2026</span>${rankMeta}<a href="https://www.shanghairanking.com/rankings/arwu/2026" target="_blank" rel="noopener">Source</a></div>
      <div class="metric-card climate-metric"><span>Exchange-period temperature</span>${climateDetails(c)}<small>NASA POWER 1991–2020 T2M climatology</small></div>
      <div class="metric-card"><span>Cost of living + rent</span>${costDetails(u)}<a href="${NUMBEO_URL}" target="_blank" rel="noopener">Numbeo source</a></div>
    </div>
    <div class="section-head"><h3 class="section-title">History & character</h3><span class="window-note">Useful for finding older institutions; campus architecture can differ</span></div>
    ${historyProfileHtml(u)}
    <div class="section-head placement-head"><h3 class="section-title">CBS placement history</h3><span class="window-note">Highlighted years are used for the current map color</span></div>
    <div class="history">${YEARS.map(y=>{const h=u.history[y],st=h.status||'unknown';return `<div class="year-card status-${esc(st)} ${windowSet.has(y)?'':'outside-window'}"><strong>${y.replace('-','–')}</strong><b>${places(u,y)}</b><span class="year-status">${esc(STATUS_META[st]?.label||h.statusLabel||'Unknown')}</span></div>`}).join('')}</div>
    <p class="summary-explain"><strong>Overall for ${esc(windowLabel())}:</strong> ${esc(STATUS_META[s.status]?.short||'No comparable years')}. ${esc(summaryExplanation(s))}</p>`;
  if(!$('#detailDialog').open)$('#detailDialog').showModal();
  if(!c)loadClimateForIds([u.id]).then(()=>{if($('#detailDialog').open&&state.currentDetailId===u.id)openDetail(u.id)}).catch(()=>{});
  if(!profile(u))loadProfileSearchOne(u).then(()=>{if($('#detailDialog').open&&state.currentDetailId===u.id)openDetail(u.id)}).catch(()=>{});
}

// Coordinates from Wikipedia, with a few city-level fallbacks for partner/campus names.
const coordKey='cbs-exchange-coords-v2';
function loadCached(){try{const c=JSON.parse(localStorage.getItem(coordKey)||'{}');for(const [id,v] of Object.entries(c))state.coords.set(Number(id),v)}catch{}for(const [id,c] of Object.entries(COORD_OVERRIDES))state.coords.set(Number(id),c)}
function saveCached(){try{localStorage.setItem(coordKey,JSON.stringify(Object.fromEntries(state.coords)))}catch{}}
async function wikiBatch(batch){const titles=batch.map(u=>u.lookupName).join('|');const url='https://en.wikipedia.org/w/api.php?action=query&format=json&origin=*&redirects=1&prop=coordinates&colimit=max&titles='+encodeURIComponent(titles);const r=await fetch(url);if(!r.ok)throw new Error('Wikipedia coordinate lookup failed');const j=await r.json();const byTitle=new Map(batch.map(u=>[u.lookupName.toLowerCase(),u]));for(const p of Object.values(j.query?.pages||{})){if(!p.coordinates?.[0])continue;let u=byTitle.get((p.title||'').toLowerCase());if(!u)u=batch.find(x=>p.title?.toLowerCase().includes(x.lookupName.toLowerCase())||x.lookupName.toLowerCase().includes((p.title||'').toLowerCase()));if(u&&!COORD_OVERRIDES[u.id])state.coords.set(u.id,{lat:p.coordinates[0].lat,lon:p.coordinates[0].lon,source:'Wikipedia'})}}
async function wikiSearchOne(u){if(COORD_OVERRIDES[u.id])return;const query=`${u.lookupName} ${u.country}`;const surl='https://en.wikipedia.org/w/api.php?action=query&format=json&origin=*&generator=search&gsrnamespace=0&gsrlimit=1&gsrsearch='+encodeURIComponent(query)+'&prop=coordinates&colimit=max';try{const r=await fetch(surl);if(!r.ok)return;const j=await r.json();const p=Object.values(j.query?.pages||{})[0];if(p?.coordinates?.[0])state.coords.set(u.id,{lat:p.coordinates[0].lat,lon:p.coordinates[0].lon,source:'Wikipedia search'})}catch{}}
async function resolveCoordinates(){
  loadCached();renderMarkers();const missing=state.all.filter(u=>!state.coords.has(u.id));
  for(let i=0;i<missing.length;i+=40){try{await wikiBatch(missing.slice(i,i+40))}catch{}$('#geoStatus').textContent=`· locating universities ${Math.min(i+40,missing.length)}/${missing.length}`;renderMarkers()}
  const still=state.all.filter(u=>!state.coords.has(u.id));for(let i=0;i<still.length;i+=6){await Promise.all(still.slice(i,i+6).map(wikiSearchOne));$('#geoStatus').textContent=`· resolving ${Math.min(i+6,still.length)}/${still.length} unmatched`;renderMarkers()}
  for(const [id,c] of Object.entries(COORD_OVERRIDES))state.coords.set(Number(id),c);
  saveCached();const unresolved=state.all.length-state.coords.size;$('#geoStatus').textContent=`· ${state.coords.size} mapped${unresolved?` · ${unresolved} unresolved`:''}`;renderMarkers();loadClimateAll();
}

// NASA POWER 1991–2020 2 m air-temperature climatology. Requests are retried because the
// public endpoint can occasionally throttle or time out.
const climateKey='cbs-exchange-nasa-power-climate-v2-1991-2020';
function gridKey(c){const lat=Math.round(c.lat*2)/2,lon=Math.round(c.lon/0.625)*0.625;return `${lat.toFixed(3)},${lon.toFixed(3)}`}
function loadClimateCache(){try{const c=JSON.parse(localStorage.getItem(climateKey)||'{}');for(const [k,v] of Object.entries(c))state.gridClimate.set(k,v)}catch{}}
function saveClimateCache(){try{localStorage.setItem(climateKey,JSON.stringify(Object.fromEntries(state.gridClimate)))}catch{}}
const wait=ms=>new Promise(r=>setTimeout(r,ms));
async function fetchGridClimate(c){
  const key=gridKey(c);if(state.gridClimate.has(key))return state.gridClimate.get(key);
  const url=`https://power.larc.nasa.gov/api/temporal/climatology/point?parameters=T2M&community=SB&longitude=${encodeURIComponent(c.lon)}&latitude=${encodeURIComponent(c.lat)}&format=JSON&start=1991&end=2020`;
  let lastErr=null;for(let attempt=0;attempt<3;attempt++){try{const ctl=new AbortController();const timer=setTimeout(()=>ctl.abort(),15000);const r=await fetch(url,{signal:ctl.signal,cache:'no-store'});clearTimeout(timer);if(!r.ok)throw new Error(`NASA POWER ${r.status}`);const j=await r.json();const p=j?.properties?.parameter?.T2M;if(!p)throw new Error('No T2M climate data');const v={SEP:Number(p.SEP),OCT:Number(p.OCT),NOV:Number(p.NOV),DEC:Number(p.DEC)};if(!Object.values(v).every(Number.isFinite))throw new Error('Incomplete climate data');state.gridClimate.set(key,v);return v}catch(e){lastErr=e;await wait(350*(attempt+1))}}throw lastErr||new Error('Climate request failed');
}
function refreshDataStatus(){
  const arwu=state.arwuReady?`ARWU: ${state.arwuRankedCount} matched · ${state.arwuPendingCount} no confident match`:'ARWU: loading';
  const climate=state.climateLoading?`Climate: ${state.climateDone}/${state.climateTotal} locations`:`Climate: ${state.climate.size}/${state.all.length} loaded`;
  const hist=state.profileLoading?`History: ${state.profileDone}/${state.profileTotal}`:`History: ${state.profiles.size}/${state.all.length}`;
  $('#dataStatus').textContent=`${arwu} · ${climate} · ${hist}`;
}
async function loadClimateForIds(ids){const groups=new Map();for(const id of ids){if(state.climate.has(id))continue;const c=state.coords.get(id);if(!c)continue;const k=gridKey(c);if(!groups.has(k))groups.set(k,{c,ids:[]});groups.get(k).ids.push(id)}for(const g of groups.values()){try{const v=await fetchGridClimate(g.c);for(const id of g.ids)state.climate.set(id,v)}catch(e){console.warn('Climate unavailable for',g.ids,e)}}saveClimateCache();renderTable();renderMarkers();refreshDataStatus()}
async function loadClimateAll(){
  if(state.climateLoading)return;loadClimateCache();const groups=new Map();for(const u of state.all){const c=state.coords.get(u.id);if(!c)continue;const k=gridKey(c);if(!groups.has(k))groups.set(k,{c,ids:[]});groups.get(k).ids.push(u.id)}
  for(const g of groups.values()){const cached=state.gridClimate.get(gridKey(g.c));if(cached)for(const id of g.ids)state.climate.set(id,cached)}
  const pending=[...groups.values()].filter(g=>!state.gridClimate.has(gridKey(g.c)));state.climateLoading=true;state.climateDone=groups.size-pending.length;state.climateTotal=groups.size;refreshDataStatus();renderTable();let next=0;
  async function worker(){while(next<pending.length){const i=next++,g=pending[i];try{const v=await fetchGridClimate(g.c);for(const id of g.ids)state.climate.set(id,v)}catch(e){console.warn('Climate unavailable for',g.ids,e)}state.climateDone++;if(state.climateDone%5===0||state.climateDone===state.climateTotal){saveClimateCache();refreshDataStatus();applyFilters()}await wait(120)}}
  await Promise.all(Array.from({length:Math.min(3,pending.length||1)},worker));state.climateLoading=false;saveClimateCache();refreshDataStatus();applyFilters();
}

// University age and short background: Wikipedia intro + Wikidata inception (P571).
const profileKey='cbs-exchange-profiles-v2';
function loadProfileCache(){try{const p=JSON.parse(localStorage.getItem(profileKey)||'{}');for(const [id,v] of Object.entries(p))state.profiles.set(Number(id),v)}catch{}}
function saveProfileCache(){try{localStorage.setItem(profileKey,JSON.stringify(Object.fromEntries(state.profiles)))}catch{}}
function titleAliases(query){const m=new Map();for(const x of query?.normalized||[])m.set(x.from,x.to);for(const x of query?.redirects||[])m.set(x.from,x.to);return m}
function resolveAlias(title,aliases){let t=title;for(let i=0;i<4&&aliases.has(t);i++)t=aliases.get(t);return t}
function pageToProfile(p,method='title'){return {wikiTitle:p.title||null,wikiUrl:p.fullurl||null,extract:(p.extract||'').trim(),qid:p.pageprops?.wikibase_item||null,foundedYear:null,matchMethod:method}}
async function fetchFoundedForProfiles(items){const byQ=new Map(items.filter(x=>x.p?.qid).map(x=>[x.p.qid,x]));if(!byQ.size)return;const ids=[...byQ.keys()];for(let i=0;i<ids.length;i+=50){const batch=ids.slice(i,i+50);try{const url='https://www.wikidata.org/w/api.php?action=wbgetentities&format=json&origin=*&props=claims&ids='+encodeURIComponent(batch.join('|'));const r=await fetch(url);if(!r.ok)continue;const j=await r.json();for(const qid of batch){const ent=j.entities?.[qid],item=byQ.get(qid);const claims=ent?.claims?.P571||[];const years=claims.map(c=>c?.mainsnak?.datavalue?.value?.time).filter(Boolean).map(t=>{const m=String(t).match(/^\+?(\d{1,4})-/);return m?Number(m[1]):null}).filter(y=>Number.isFinite(y)&&y>0&&y<=new Date().getFullYear());if(years.length)item.p.foundedYear=Math.min(...years)}}catch(e){console.warn('Wikidata founded-year lookup failed',e)}}}
async function loadProfileBatch(batch){
  const titles=batch.map(u=>u.lookupName).join('|');const url='https://en.wikipedia.org/w/api.php?action=query&format=json&origin=*&redirects=1&prop=pageprops%7Cextracts%7Cinfo&exintro=1&explaintext=1&exsentences=3&inprop=url&titles='+encodeURIComponent(titles);
  const r=await fetch(url);if(!r.ok)throw new Error('Wikipedia profile lookup failed');const j=await r.json(),pages=Object.values(j.query?.pages||{}).filter(p=>!p.missing),aliases=titleAliases(j.query),byTitle=new Map(pages.map(p=>[(p.title||'').toLowerCase(),p])),items=[];
  for(const u of batch){const resolved=resolveAlias(u.lookupName,aliases),p=byTitle.get(resolved.toLowerCase());if(p){const prof=pageToProfile(p,'title');items.push({u,p:prof});state.profiles.set(u.id,prof)}}
  await fetchFoundedForProfiles(items);for(const {u,p} of items)state.profiles.set(u.id,p);return new Set(items.map(x=>x.u.id));
}
async function loadProfileSearchOne(u){
  if(state.profiles.has(u.id))return state.profiles.get(u.id);const query=`${u.lookupName} ${u.country} university`;const url='https://en.wikipedia.org/w/api.php?action=query&format=json&origin=*&generator=search&gsrnamespace=0&gsrlimit=1&gsrsearch='+encodeURIComponent(query)+'&prop=pageprops%7Cextracts%7Cinfo%7Ccoordinates&exintro=1&explaintext=1&exsentences=3&inprop=url';
  try{const r=await fetch(url);if(!r.ok)throw new Error('Wikipedia search failed');const j=await r.json(),p=Object.values(j.query?.pages||{})[0];if(!p)return null;const prof=pageToProfile(p,'search');await fetchFoundedForProfiles([{u,p:prof}]);state.profiles.set(u.id,prof);if(p.coordinates?.[0]&&!state.coords.has(u.id)&&!COORD_OVERRIDES[u.id]){state.coords.set(u.id,{lat:p.coordinates[0].lat,lon:p.coordinates[0].lon,source:'Wikipedia profile search'});saveCached()}saveProfileCache();applyFilters();refreshDataStatus();return prof}catch(e){console.warn('Profile search failed for',u.name,e);return null}
}
async function loadProfilesBackground(){
  loadProfileCache();state.profileTotal=state.all.length;const missing=state.all.filter(u=>!state.profiles.has(u.id));if(!missing.length){$('#foundedBefore').disabled=false;refreshDataStatus();return}state.profileLoading=true;state.profileDone=state.profiles.size;refreshDataStatus();const unresolved=[];
  for(let i=0;i<missing.length;i+=20){const batch=missing.slice(i,i+20);let hit=new Set();try{hit=await loadProfileBatch(batch)}catch(e){console.warn('Profile batch failed',e)}for(const u of batch)if(!hit.has(u.id))unresolved.push(u);state.profileDone=state.profiles.size;saveProfileCache();refreshDataStatus();if(i%40===0)applyFilters();await wait(80)}
  let next=0;async function worker(){while(next<unresolved.length){const u=unresolved[next++];await loadProfileSearchOne(u);state.profileDone=state.profiles.size;refreshDataStatus();await wait(130)}}await Promise.all(Array.from({length:Math.min(3,unresolved.length||1)},worker));state.profileLoading=false;$('#foundedBefore').disabled=false;saveProfileCache();refreshDataStatus();applyFilters();
}

function rankLower(rank){if(!rank)return null;const m=String(rank).match(/\d+/);return m?Number(m[0]):null}
async function loadArwu(){
  let entries={},fileComplete=false;try{const r=await fetch('data/arwu2026.json',{cache:'no-store'});if(r.ok){const j=await r.json();entries=j.universities||j;fileComplete=(j.status==='complete')}}catch(e){console.warn('Optional ARWU file unavailable; using built-in verified matches',e)}
  let ranked=0,unmatched=0;for(const u of state.all){const id=String(u.id),x=fileComplete&&entries[id]!==undefined?entries[id]:BUILTIN_ARWU[id];if(!x){u.arwuRank=null;u.arwuSort=null;u.arwuMatchedInstitution=null;u.arwuPending=false;u.arwuUnmatched=true;unmatched++;continue}const rank=typeof x==='object'&&x!==null?x.rank:x;u.arwuRank=rank||null;u.arwuSort=rankLower(rank);u.arwuMatchedInstitution=(typeof x==='object'&&x)?x.matchedInstitution:null;u.arwuPending=false;u.arwuUnmatched=!u.arwuRank;if(u.arwuRank)ranked++;else unmatched++}
  state.arwuRankedCount=ranked;state.arwuPendingCount=unmatched;state.arwuReady=true;refreshDataStatus();applyFilters();
}

async function init(){
  const r=await fetch('data/universities.json');state.all=await r.json();state.filtered=[...state.all];loadProfileCache();
  const countries=[...new Set(state.all.map(u=>u.country))].sort();$('#totalCount').textContent=state.all.length;$('#countryCount').textContent=countries.length;
  const countrySelect=$('#country');countrySelect.innerHTML='<option value="">All countries</option>'+countries.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');
  // Continent options are deliberately present in the HTML as well as validated here, so they work even before async data finishes loading.
  const continentSelect=$('#continent'),validContinents=new Set(state.all.map(continent));
  for(const opt of [...continentSelect.options])if(opt.value&&!validContinents.has(opt.value))opt.remove();
  for(const el of ['search','country','continent','minPlaces','historyWindow','demandLevel','arwuMax','tempMetric','minTemp','maxCost','foundedBefore','last2'])$('#'+el).addEventListener(el==='search'?'input':'change',applyFilters);
  $('#reset').addEventListener('click',resetAllFilters);
  document.querySelectorAll('th[data-sort]').forEach(th=>th.addEventListener('click',()=>{const k=th.dataset.sort;if(state.sortKey===k)state.sortDir*=-1;else{state.sortKey=k;state.sortDir=(k==='name'||k==='country'||k==='arwuSort'||k==='demandScore'||k==='costIndex'||k==='foundedYear')?1:-1}renderTable()}));
  $('#mapBtn').addEventListener('click',()=>switchView('map'));$('#listBtn').addEventListener('click',()=>switchView('list'));$('#closeDialog').addEventListener('click',()=>{$('#detailDialog').close();state.currentDetailId=null});
  loadClimateCache();applyFilters();loadArwu();resolveCoordinates();loadProfilesBackground();refreshDataStatus();
}
function switchView(v){const isMap=v==='map';$('#mapView').classList.toggle('active',isMap);$('#listView').classList.toggle('active',!isMap);$('#mapBtn').classList.toggle('active',isMap);$('#listBtn').classList.toggle('active',!isMap);if(isMap)setTimeout(()=>map.invalidateSize(),50)}
init().catch(e=>{$('#geoStatus').textContent='· could not load dataset';console.error(e)});
